CREATE TABLE fare_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category text NOT NULL,base_paise integer NOT NULL CHECK(base_paise>=0),per_km_paise integer NOT NULL CHECK(per_km_paise>=0),version integer NOT NULL);
CREATE TABLE fare_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),policy_id uuid REFERENCES fare_policies(id),amount_paise integer NOT NULL CHECK(amount_paise>=0),expires_at timestamptz NOT NULL);
CREATE TABLE ride_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),passenger_id uuid REFERENCES users(id),pickup geography(Point,4326) NOT NULL,dropoff geography(Point,4326) NOT NULL,category text NOT NULL CHECK(category IN ('AUTO','TAXI')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private_bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid UNIQUE REFERENCES ride_requests(id),passenger_id uuid NOT NULL REFERENCES users(id),driver_id uuid REFERENCES users(id),vehicle_id uuid REFERENCES vehicles(id),status text NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','ACCEPTED','ARRIVED','IN_PROGRESS','COMPLETED','CANCELLED')),fare_paise integer NOT NULL CHECK(fare_paise>=0),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX driver_one_active_private ON private_bookings(driver_id) WHERE status IN ('ACCEPTED','ARRIVED','IN_PROGRESS');
CREATE TABLE shared_trips(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),driver_id uuid NOT NULL REFERENCES users(id),vehicle_id uuid NOT NULL REFERENCES vehicles(id),departure_at timestamptz NOT NULL,capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 12),fare_paise integer NOT NULL CHECK(fare_paise>=0),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','BOARDING','IN_PROGRESS','COMPLETED','CANCELLED')),bookings_open boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1);
CREATE TABLE shared_trip_stops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid NOT NULL REFERENCES shared_trips(id),name text NOT NULL,point geography(Point,4326) NOT NULL,sequence integer NOT NULL CHECK(sequence>=0),UNIQUE(trip_id,sequence));
CREATE TABLE seat_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trip_id uuid NOT NULL REFERENCES shared_trips(id),passenger_id uuid NOT NULL REFERENCES users(id),pickup_sequence integer NOT NULL,dropoff_sequence integer NOT NULL,seats integer NOT NULL CHECK(seats BETWEEN 1 AND 12),fare_paise integer NOT NULL CHECK(fare_paise>=0),status text NOT NULL DEFAULT 'CONFIRMED' CHECK(status IN ('CONFIRMED','BOARDED','CANCELLED','NO_SHOW','COMPLETED','EXPIRED')),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(pickup_sequence<dropoff_sequence),FOREIGN KEY(trip_id,pickup_sequence) REFERENCES shared_trip_stops(trip_id,sequence),FOREIGN KEY(trip_id,dropoff_sequence) REFERENCES shared_trip_stops(trip_id,sequence));
CREATE UNIQUE INDEX passenger_one_reservation ON seat_reservations(trip_id,passenger_id) WHERE status IN ('CONFIRMED','BOARDED');
CREATE TABLE passenger_boarding_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reservation_id uuid REFERENCES seat_reservations(id),actor_id uuid REFERENCES users(id),kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE booking_state_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,booking_id uuid REFERENCES private_bookings(id),actor_id uuid REFERENCES users(id),from_state text,to_state text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid REFERENCES private_bookings(id),reservation_id uuid REFERENCES seat_reservations(id),amount_paise integer NOT NULL CHECK(amount_paise>=0),method text NOT NULL CHECK(method IN ('CASH','GATEWAY')),status text NOT NULL CHECK(status IN ('PENDING','SUCCEEDED','FAILED','REFUNDED')),provider_reference text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(booking_id,reservation_id)=1));
CREATE UNIQUE INDEX one_booking_payment ON payments(booking_id) WHERE status='SUCCEEDED';
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid REFERENCES payments(id),amount_paise integer NOT NULL CHECK(amount_paise>0),status text NOT NULL DEFAULT 'REQUESTED',reason text NOT NULL);
CREATE TABLE payouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),driver_id uuid REFERENCES users(id),amount_paise integer NOT NULL CHECK(amount_paise>0),status text NOT NULL DEFAULT 'PENDING',provider_reference text UNIQUE);
CREATE TABLE ledger_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id uuid REFERENCES payments(id),payout_id uuid REFERENCES payouts(id),account text NOT NULL,amount_paise bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial ledger is append only'; END $$;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TABLE ratings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid REFERENCES private_bookings(id),passenger_id uuid REFERENCES users(id),stars integer CHECK(stars BETWEEN 1 AND 5),UNIQUE(booking_id,passenger_id));
CREATE TABLE support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),subject text NOT NULL,status text NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE complaints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid REFERENCES users(id),booking_id uuid REFERENCES private_bookings(id),description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
